-- Prometeo DataGrip test fixture for PostgreSQL. Idempotent: recreates schema "shop".
drop schema if exists shop cascade;
create schema shop;
comment on schema shop is 'Demo shop';

create type shop.order_status as enum ('new', 'paid', 'shipped', 'cancelled');

create table shop.categories (
    id         serial primary key,
    name       varchar(100) not null unique,
    parent_id  integer references shop.categories (id) on delete set null
);
comment on table shop.categories is 'Product categories';

create table shop.products (
    id           integer generated by default as identity primary key,
    sku          varchar(32) not null,
    name         varchar(255) not null,
    category_id  integer not null references shop.categories (id),
    price        numeric(10, 2) not null,
    stock        integer not null default 0,
    tags         text[] not null default '{}',
    created_at   timestamptz not null default now(),
    updated_at   timestamptz,
    constraint products_sku_key unique (sku),
    constraint products_price_positive check (price > 0)
);
create index idx_products_category on shop.products (category_id);
create index idx_products_name_lower on shop.products (lower(name));
create index idx_products_low_stock on shop.products (stock) where stock < 5;

create table shop.customers (
    id          serial primary key,
    email       varchar(255) not null unique,
    name        varchar(255) not null,
    vip         boolean not null default false,
    created_at  timestamp not null default now()
);

create table shop.orders (
    id           serial primary key,
    customer_id  integer not null references shop.customers (id) on delete cascade,
    status       shop.order_status not null default 'new',
    placed_at    timestamptz not null default now(),
    note         text
);
create index idx_orders_customer on shop.orders (customer_id);

create table shop.order_items (
    order_id    integer not null references shop.orders (id) on delete cascade,
    line_no     integer not null,
    product_id  integer not null references shop.products (id),
    qty         integer not null check (qty > 0),
    unit_price  numeric(10, 2) not null,
    primary key (order_id, line_no)
);

create sequence shop.invoice_seq start 1000 increment 5;

create function shop.touch_updated_at() returns trigger language plpgsql as $$
begin
    new.updated_at := now();
    return new;
end;
$$;
create trigger trg_products_touch before update on shop.products
    for each row execute function shop.touch_updated_at();

create function shop.order_total(p_order_id integer) returns numeric language sql stable as $$
    select coalesce(sum(qty * unit_price), 0) from shop.order_items where order_id = p_order_id;
$$;

create procedure shop.restock(p_id integer, p_qty integer) language plpgsql as $$
begin
    update shop.products set stock = stock + p_qty where id = p_id;
end;
$$;

insert into shop.categories (name, parent_id) values
    ('Electronics', null), ('Books', null), ('Garden', null), ('Laptops', 1), ('Phones', 1);

insert into shop.products (sku, name, category_id, price, stock, tags)
select 'SKU-' || lpad(g::text, 4, '0'),
       'Product ' || g,
       1 + (g % 5),
       round((5 + g * 3.37)::numeric, 2),
       (g * 7) % 40,
       case when g % 3 = 0 then array['sale', 'new'] else array['std'] end
from generate_series(1, 20) g;

insert into shop.customers (email, name, vip)
select 'customer' || g || '@example.com', 'Customer ' || g, g % 4 = 0 from generate_series(1, 10) g;

insert into shop.orders (customer_id, status, placed_at, note)
select 1 + (g % 10), (array['new','paid','shipped','cancelled'])[1 + (g % 4)]::shop.order_status,
       timestamptz '2024-01-01 10:00:00+00' + g * interval '1 day', case when g % 5 = 0 then 'gift wrap' end
from generate_series(1, 30) g;

insert into shop.order_items (order_id, line_no, product_id, qty, unit_price)
select o, l, 1 + ((o * 3 + l) % 20), 1 + (o + l) % 4, round((10 + o * 1.5 + l)::numeric, 2)
from generate_series(1, 30) o, generate_series(1, 3) l;

create view shop.v_order_totals as
select o.id as order_id, c.name as customer, o.status, shop.order_total(o.id) as total
from shop.orders o join shop.customers c on c.id = o.customer_id;

create materialized view shop.mv_sales_by_category as
select cat.name as category, sum(oi.qty * oi.unit_price) as revenue
from shop.order_items oi
join shop.products p on p.id = oi.product_id
join shop.categories cat on cat.id = p.category_id
group by cat.name;
create unique index mv_sales_by_category_pk on shop.mv_sales_by_category (category);

-- a table with many column types
create table shop.all_types (
    id            serial primary key,
    c_smallint    smallint,
    c_int         integer,
    c_bigint      bigint,
    c_numeric     numeric(30, 10),
    c_real        real,
    c_double      double precision,
    c_bool        boolean,
    c_text        text,
    c_varchar     varchar(40),
    c_char        char(5),
    c_bytea       bytea,
    c_uuid        uuid,
    c_json        json,
    c_jsonb       jsonb,
    c_date        date,
    c_time        time,
    c_timetz      timetz,
    c_timestamp   timestamp,
    c_timestamptz timestamptz,
    c_interval    interval,
    c_inet        inet,
    c_cidr        cidr,
    c_macaddr     macaddr,
    c_int_arr     integer[],
    c_text_arr    text[],
    c_enum        shop.order_status,
    c_enum_arr    shop.order_status[],
    c_money       money,
    c_bit         bit(8),
    c_varbit      varbit(16),
    c_xml         xml,
    c_point       point,
    c_tsvector    tsvector,
    c_int4range   int4range
);
insert into shop.all_types (c_smallint, c_int, c_bigint, c_numeric, c_real, c_double, c_bool, c_text, c_varchar, c_char,
    c_bytea, c_uuid, c_json, c_jsonb, c_date, c_time, c_timetz, c_timestamp, c_timestamptz, c_interval, c_inet, c_cidr,
    c_macaddr, c_int_arr, c_text_arr, c_enum, c_enum_arr, c_money, c_bit, c_varbit, c_xml, c_point, c_tsvector, c_int4range)
values (32767, 2147483647, 9223372036854775807, 12345678901234567890.1234567890, 1.5, 1.2345678901234567, true,
    E'multi\nline "text" with ''quotes'' and unicode: éñ 😀', 'varchar', 'ab',
    '\xdeadbeef', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11', '{"a": [1, 2, {"b": null}]}', '{"k": "v", "n": 1.50}',
    '2024-02-29', '13:45:10.123456', '13:45:10+02', '2024-02-29 13:45:10.5', '2024-02-29 13:45:10+00', '1 year 2 mons 3 days 04:05:06',
    '192.168.1.10', '10.0.0.0/8', '08:00:2b:01:02:03', '{1,2,NULL,4}', '{"a b","c,d","e\"f",NULL}', 'paid', '{new,shipped}',
    '$1,234.50', B'10101010', B'101', '<root a="1"/>', '(1.5,2.5)', 'fat cat'::tsvector, '[1,10)');
insert into shop.all_types (id) values (2);

-- big table for paging / performance checks
create table shop.big_table (
    id       integer primary key,
    grp      integer not null,
    name     text not null,
    amount   numeric(12, 2) not null,
    created  timestamptz not null,
    payload  text
);
insert into shop.big_table
select g, g % 100, 'name-' || g, round((g * 1.37)::numeric, 2), timestamptz '2024-01-01 00:00:00+00' + g * interval '1 minute',
       md5(g::text)
from generate_series(1, 100000) g;
create index idx_big_grp on shop.big_table (grp);
analyze shop.big_table;
